export const AppIcon = React.memo(({ name, className, style }) => {
  const icon = ICON_CONFIGS[name];
  
  if (!icon) return null;

  return (
    <svg 
      className={className} 
      style={style} 
      viewBox={icon.viewBox} 
      fill="none" 
      xmlns="http://www.w3.org/2000/svg"
    >
      {icon.content}
    </svg>
  );
});

AppIcon.displayName = "AppIcon";
